[CmdletBinding()]param([Parameter(Mandatory=$true)][string]$Day)
$ErrorActionPreference='Stop';$repository=Split-Path -Parent $PSScriptRoot;$python=Join-Path $repository '.venv\Scripts\python.exe';$credential=Join-Path $env:LOCALAPPDATA 'Hermes\Databento\es-nq-historical\credential.dpapi';$output=Join-Path $repository 'outputs\futures_data\databento_lineage.json';$pointer=[IntPtr]::Zero;$plain=$null
try{$secure=(Get-Content $credential -Raw)|ConvertTo-SecureString;$pointer=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure);$plain=[Runtime.InteropServices.Marshal]::PtrToStringBSTR($pointer);$info=[Diagnostics.ProcessStartInfo]::new();$info.FileName=$python;$info.WorkingDirectory=$repository;$info.Arguments='-m futures_data.databento_lineage_probe --day "'+$Day+'" --output "'+$output+'"';$info.UseShellExecute=$false;$info.RedirectStandardInput=$true;$info.RedirectStandardOutput=$true;$info.RedirectStandardError=$true;$info.CreateNoWindow=$true;$p=[Diagnostics.Process]::new();$p.StartInfo=$info;if(!$p.Start()){throw 'Lineage probe start failed'};$p.StandardInput.WriteLine($plain);$p.StandardInput.Close();$plain=$null;$p.WaitForExit();$out=$p.StandardOutput.ReadToEnd();$err=$p.StandardError.ReadToEnd().Trim();if($p.ExitCode-ne 0){throw $err};$out}finally{if($pointer-ne[IntPtr]::Zero){[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($pointer)};$plain=$null;$secure=$null}
